def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate groups of nested parentheses into separate strings.

    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, where each string represents a separate group of parentheses.
    """
    result = []
    stack = []
    current_group = ''

    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack.pop()
            if len(stack) == 0:
                result.append(current_group)
                current_group = ''
        else:
            current_group += char

    if len(stack) != 0:
        raise ValueError("Invalid input string. Unbalanced parentheses.")

    return result

