def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table with the values at the top row and left column
    table = [[grid_values[0][2]] * N for _ in range(N)]

    # Fill in the table with the maximum values for each cell
    for i in range(1, N):
        for j in range(1, N):
            table[i][j] = max(table[i - 1][j], table[i][j - 1], table[i - 1][j - 1])

    # Return the maximum sum of values collected on the two paths
    return table[N - 1][N - 1]

