def verify_isbn(isbn: str) -> str:
    isbn_list = list(isbn)
    checksum = 0
    for i in range(len(isbn_list)):
        if isbn_list[i] != '-' and isbn_list[i].isdigit():
            checksum += (len(isbn_list) - i) * int(isbn_list[i])
    if checksum % 11 == 0:
        return "Right"
    else:
