def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    letter_mapping = {}
    for i in range(len(encoded)):
        letter_mapping[encoded[i]] = original[i]

    # Use the mapping to decode the message
    decoded_message = ""
    for letter in message:
        if letter in letter_mapping:
            decoded_message += letter_mapping[letter]
        else:
            return "Failed"

    return decoded_message

