def count_partitions(n, k, x):
    # Initialize a 2D array to store the results
    dp = [[0] * (k+1) for _ in range(n+1)]

    # Initialize the first row and column with 1s
    for i in range(n+1):
        dp[i][0] = 1
    for i in range(k+1):
        dp[0][i] = 1

    # Fill in the rest of the array
    for i in range(1, n+1):
        for j in range(1, k+1):
            for l in range(1, i+1):
                if l >= x:
                    dp[i][j] += dp[i-l][j-1]

    # Return the number of partitions
    return dp[n][k]

def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if last <= 0:
        return 0
    if last == 1:
        return 1
    count = 0
    for i in range(1, last):
        if i <= last // 2:
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count

