def max_herb_value(T, M, herbs):
    # Initialize the dp table with 0 for all indices
    dp = [0] * (M + 1)

    # Loop through the herbs and update the dp table
    for i in range(1, M + 1):
        for j in range(T + 1):
            # Check if the current herb can be picked at the current time
            if j >= herbs[i - 1][0]:
                # Update the dp table with the maximum value
                dp[i] = max(dp[i], dp[i - 1] + herbs[i - 1][1])
            else:
                # Update the dp table with the previous maximum value
                dp[i] = max(dp[i], dp[i - 1])

    # Return the maximum total value of herbs that can be picked within the time limit
    return dp[M]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a dictionary to store the maximum volume that can be occupied
    # by any subset of items with volumes up to i
    dp = {0: 0}

    # Loop through the items and their volumes
    for i in range(n):
        # Loop through the previous items and their volumes
        for j in range(i):
            # If the current item fits in the box, update the maximum volume
            if volumes[i] + dp[j] <= V:
                dp[i + 1] = max(dp[i + 1], dp[j] + volumes[i])
            # If the current item does not fit in the box, update the maximum volume
            else:
                dp[i + 1] = max(dp[i + 1], dp[j])

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n]

